cd /tmp && python3 -c "
import dataclasses as dc
from sqlparse.formatter import FormatConfig, SplitConfig, ParseConfig
spec = {
 'FormatConfig': dict(keyword_case='upper', identifier_case=None, strip_comments=False, reindent=True,
    indent_width=2, comma_first=False, use_space_around_operators=False, right_margin=None),
 'SplitConfig': dict(keep_trailing_semicolon=True, strip_whitespace=True),
 'ParseConfig': dict(dialect='default', error_mode='strict'),
}
for cls in (FormatConfig, SplitConfig, ParseConfig):
    print('==', cls.__name__, 'is_dataclass=', dc.is_dataclass(cls), 'frozen=', cls.__dataclass_params__.frozen)
    actual = {f.name: f.default for f in dc.fields(cls)}
    print('   actual fields:', actual)
    exp = spec[cls.__name__]
    print('   names match exactly:', list(actual.keys()) == list(exp.keys()))
    for k,v in exp.items():
        if k not in actual: print('   MISSING FIELD', k)
        elif actual[k] != v or type(actual[k]) is not type(v): print(f'   DEFAULT MISMATCH {k}: {actual[k]!r} != {v!r}')
    for k in actual:
        if k not in exp: print('   EXTRA FIELD', k)
    inst = cls()
    print('   default instance:', inst)
    try:
        object.__setattr__  # noop
        setattr(inst, list(actual)[0], 'zzz'); print('   FROZEN CHECK FAILED - mutation allowed')
    except dc.FrozenInstanceError as e: print('   FrozenInstanceError OK')
    except Exception as e: print('   other exc', type(e).__name__, e)
    print('   as_options():', inst.as_options() if hasattr(inst,'as_options') else 'NO as_options')
"

